var SPR=[["Assisted Aim (GH14C)",1,"Enchantment",["Bard","Cleric","Druid","Paladin","Ranger"],"Action","30 ft","V, S","1 minute",0,0,"","30 ft, 1 minute. Up to three creatures get +1 to ranged weapon attacks and double weapon range.","GHCG14",["Bard","Cleric","Druid","Paladin","Ranger"]],["Conjure Plants (GH14C)",3,"Conjuration",["Druid","Ranger","Warlock"],"Action","60 ft","V, S, M","Up to 1 hour",1,0,"","60 ft, 1 hour, Concentration. Animate plants as friendly elementals: one CR 2, two CR 1, four CR 1/2 or eight CR 1/4.","GHCG14",["Druid","Ranger","Warlock"]],["Curse of Conceited Obsession (GH14C)",6,"Enchantment",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"CHA","Self, until cured, 1-hour cast. Charisma save or a vanity curse that ends in a Weeping Willow.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Damned Aging (GH14C)",4,"Necromancy",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"STR","Self, until cured, 1-hour cast. Strength save or a withering curse that ends in a Body Snatcher.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Foul Blight (GH14C)",4,"Necromancy",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"CHA","Self, until cured, 1-hour cast. Charisma save or a putrid pox curse that ends in a Plague Carrion.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Ill-Fated Fortune (GH14C)",5,"Divination",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"DEX","Self, until cured, 1-hour cast. Dexterity save or a bad luck curse that ends in a Herald of Calamity.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Insatiable Greed (GH14C)",5,"Enchantment",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"WIS","Self, until cured, 1-hour cast. Wisdom save or a greed curse that ends in a Verminous Abomination.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Lost Sentiment (GH14C)",4,"Enchantment",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"INT","Self, until cured, 1-hour cast. Intelligence save or a memory-loss curse that ends in a Dream Whisperer.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Ravenous Hunger (GH14C)",5,"Enchantment",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"CON","Self, until cured, 1-hour cast. Constitution save or a starvation curse that ends in a Bloated Gastromorph.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Curse of Uncontrollable Wrath (GH14C)",6,"Enchantment",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"1 hour","Self","V, S, M","Until dispelled",0,0,"WIS","Self, until cured, 1-hour cast. Wisdom save or a rage curse that ends in an Avatar of Slaughter.","GHCG14",["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"]],["Dazing Blast (GH14C)",2,"Evocation",["Sorcerer","Warlock","Wizard"],"Action","60 ft","V, S","Instantaneous",0,0,"CON","60 ft, instant. Spell attack for 2d6 Force damage. On a hit, Constitution save or Dazed until the end of its next turn.","GHCG14",["Sorcerer","Warlock","Wizard"]],["Greater Animate Dead (GH14C)",5,"Necromancy",["Cleric","Wizard"],"1 minute","10 ft","V, S, M","Instantaneous",0,0,"","10 ft, instant, 1-minute cast, night only. Raise Large or smaller undead of total CR 2 or lower from corpses.","GHCG14",["Cleric","Wizard"]],["Holy Word (GH14C)",0,"Evocation",["Cleric"],"Action","60 ft","V, S","Instantaneous",0,0,"","60 ft, instant. Ranged spell attack for 1d8 Radiant. Undead, fiends and fey also slow and lose reactions.","GHCG14",["Cleric"]],["Illusory Instrument (GH14C)",0,"Illusion",["Bard","Warlock"],"Action","Touch","V, S","10 minutes",0,0,"CON","Touch, 10 minutes. An illusory musical instrument that works as a focus and can mimic sounds, play a beat or record.","GHCG14",["Bard","Warlock"]],["Intaglio (GH14C)",1,"Transmutation",["Bard","Cleric","Paladin","Wizard"],"Action","5 ft","V, S, M","Up to 1 hour",1,1,"","5 ft, 1 hour, Concentration. Copy non-magical text or images from a surface onto parchment, one page per action.","GHCG14",["Bard","Cleric","Paladin","Wizard"]],["Life Tether (GH14C)",2,"Necromancy",["Cleric","Sorcerer","Warlock","Wizard"],"Action","120 ft","V, S","Up to 1 minute",1,0,"WIS","120 ft, 1 minute, Concentration. Wisdom save or a tether shares half the damage you take as Necrotic damage.","GHCG14",["Cleric","Sorcerer","Warlock","Wizard"]],["Mirror Spell (GH14C)",3,"Abjuration",["Sorcerer","Warlock","Wizard"],"Reaction","60 ft","V, S","Instantaneous",0,0,"CON","60 ft, instant, reaction when you see a spell cast within 60 ft. Copy a spell of your slot level or lower and cast it.","GHCG14",["Sorcerer","Warlock","Wizard"]],["Undead Enthrallment (GH14C)",8,"Necromancy",["Cleric","Warlock","Wizard"],"1 hour","10 ft","V, S, M","Instantaneous",0,0,"","10 ft, instant, 1-hour cast, night only. Raise corpses as undead of CR 3 or lower, up to four under your control permanently.","GHCG14",["Cleric","Warlock","Wizard"]]];
var SPF={"Assisted Aim (GH14C)":"30 ft, 1 minute. You sharpen the aim of up to three creatures in range. Each gains +1 to hit with ranged weapon attacks and doubles the normal and long range of weapons it wields.\n\n**At Higher Levels.** Target one more creature for each slot level above 1st.","Conjure Plants (GH14C)":"60 ft, up to 1 hour, Concentration. You call on the Primordials to animate plants in open, unoccupied space in range. If there is no room, the GM may make plants grow fast and decides how many. Choose one: one plant of CR 2 or lower, two of CR 1 or lower, four of CR 1/2 or lower, or eight of CR 1/4 or lower. Each plant counts as an elemental as well as its other types and turns back into a normal plant at 0 hit points or when the spell ends. They are friendly to you and your companions. Roll initiative for them as a group. They obey your spoken commands with no action from you. With no command they defend themselves. The GM has their statistics.\n\n**At Higher Levels.** With a 5th level slot there are twice as many, with 7th three times, with 9th four times.","Curse of Conceited Obsession (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Charisma save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** The next time the target looks into a mirror or reflective surface, it cracks.\n**Stage 1.** It stops to admire itself whenever it sees its reflection.\n**Stage 2.** It obsessively seeks its reflection everywhere. It has Disadvantage on attack rolls.\n**Stage 3.** It must find or build a place where it sees itself from many angles and stays there to admire itself. Attack rolls against it have Advantage.\n**Culmination.** If it fails the final escalation check, it twists into a Weeping Willow. A player character becomes an NPC under GM control.","Curse of Damned Aging (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Strength save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** The next time the target changes clothes, it finds wrinkles, grey hair and age spots.\n**Stage 1.** It rests whenever it can and grows lazy.\n**Stage 2.** Its muscles waste. It has Disadvantage on Strength saves.\n**Stage 3.** It ages fast and becomes decrepit. Its Strength becomes 6 unless already lower.\n**Culmination.** If it fails the final escalation check, it twists into a Body Snatcher. A player character becomes an NPC under GM control.","Curse of Foul Blight (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Charisma save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** When the target searches its pack or clothes, it finds an infestation of insects.\n**Stage 1.** A minor cough: it coughs when it says more than a few words.\n**Stage 2.** Rot lingers around it. Food and drink spoil, jewelry tarnishes and wood rots within 10 ft. It has Disadvantage on Charisma saves.\n**Stage 3.** Pocks and sores cover its skin and insects infest its clothes. Its Charisma becomes 6 unless already lower.\n**Culmination.** If it fails the final escalation check, it twists into a Plague Carrion. A player character becomes an NPC under GM control.","Curse of Ill-Fated Fortune (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Dexterity save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** The next time the target goes through a doorway or climbs stairs, it badly stubs its toe.\n**Stage 1.** Minor mishaps: shops close as it arrives, gear breaks at bad moments.\n**Stage 2.** Harmless setbacks turn dangerous, such as objects always in its way. It has Disadvantage on Dexterity saves.\n**Stage 3.** It is dangerously accident-prone and simple tasks have deadly side effects. Its Dexterity becomes 6 unless already lower.\n**Culmination.** If it fails the final escalation check, it twists into a Herald of Calamity. A player character becomes an NPC under GM control.","Curse of Insatiable Greed (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Wisdom save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** The next time the target finishes a Long Rest, it finds a valued item missing.\n**Stage 1.** It is compelled to steal trinkets it does not own.\n**Stage 2.** It makes a secret hoard and fears leaving it for long. It has Disadvantage on Wisdom saves.\n**Stage 3.** It turns its hoard into a labyrinth of stolen goods and cannot leave it. Its Wisdom becomes 6 unless already lower.\n**Culmination.** If it fails the final escalation check, it twists into a Verminous Abomination. A player character becomes an NPC under GM control.","Curse of Lost Sentiment (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Intelligence save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** The next time the target sleeps, it dreams of a loved one abandoning it.\n**Stage 1.** It forgets recent days and the names of acquaintances.\n**Stage 2.** It forgets all but its closest companions and imagines hidden threats and scheming rivals. It has Disadvantage on Intelligence saves.\n**Stage 3.** It forgets even close companions, itself and its goals, including a cure. Madness fills it with a conspiracy only it can stop, and it takes any action it thinks needed to uncover it. Its Intelligence becomes 6 unless already lower.\n**Culmination.** If it fails the final escalation check, it twists into a Dream Whisperer. A player character becomes an NPC under GM control.","Curse of Ravenous Hunger (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Constitution save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** As the target eats its next meal, it bites its tongue and its mouth fills with blood.\n**Stage 1.** It has an endless appetite.\n**Stage 2.** It must eat odd things such as coins, flowers, glass and dirt. It has Disadvantage on Constitution saves.\n**Stage 3.** It is ravenous and must eat humanoid flesh, and no other food satisfies it. Its Constitution becomes 6 unless already lower.\n**Culmination.** If it fails the final escalation check, it twists into a Bloated Gastromorph. A player character becomes an NPC under GM control.","Curse of Uncontrollable Wrath (GH14C)":"Self, until cured. You curse a creature on your plane. It makes a Wisdom save against the spell DC, adjusted by the Curse Strength Table. On a success it learns someone tried to curse it. On a failure it is cursed and does not know. When the triggering event happens, it moves to stage 1. **Trigger.** The next time the target wields a weapon or spellcasting focus, an old wound reopens.\n**Stage 1.** It becomes easily angered and aggressive.\n**Stage 2.** It is obsessed with violence and fights alone. It sours toward allies and cannot benefit from their spells or abilities.\n**Stage 3.** It lusts for blood and cannot rest while enemies live. It cannot finish a Long Rest.\n**Culmination.** If it fails the final escalation check, it twists into an Avatar of Slaughter. A player character becomes an NPC under GM control.","Dazing Blast (GH14C)":"60 ft, instant. A wave of force leaves your palms. Make a spell attack against a creature. On a hit it takes 2d6 Force damage and makes a Constitution save or is Dazed until the end of its next turn.\n\n**At Higher Levels.** The damage rises by 1d6 for each slot level above 2nd.","Greater Animate Dead (GH14C)":"10 ft, instant, casting time 1 minute. Cast only at night. Choose corpses in range matching the size of the undead you raise, as the GM decides. You animate Large or smaller undead of total CR 2 or lower. On each of your turns, use a bonus action to command any of them within 120 ft, all with the same order or each separately. You pick its action and movement for its next turn or give a general order, such as guarding a room. With no order it only defends itself. It keeps following an order until done. It stays under your control for 24 hours. To keep it longer, cast this spell on it again before the 24 hours end. That recast reasserts control over one creature instead of raising a new one and needs no components with a gp cost.\n\n**At Higher Levels.** With a 7th level slot you add 1 more CR. With a 9th level slot you add 2 more CR. Extra creatures need enough corpses or bones.","Holy Word (GH14C)":"60 ft, instant. You murmur a divine word, never louder, since such power is not for the tainted and unworthy. Make a ranged spell attack. On a hit the target takes 1d8 Radiant damage. If it is undead, a fiend or fey, its speed also drops by 10 ft and it cannot take reactions until the end of its next turn. The damage rises to 2d8 at level 5, 3d8 at level 11 and 4d8 at level 17.","Illusory Instrument (GH14C)":"Touch, 10 minutes. You make an illusory copy of an ordinary musical instrument in the shape of your fondest memory of one. It moves like the real thing, weighs nothing, and only you can touch it. You can use it as a spellcasting focus. It fades if you move more than 10 ft from it or end the spell. As a bonus action you can command one effect: mimic everyday sounds such as birdsong, footsteps or a slammed door; play a basic beat at a tempo you choose; record what is played on it and loop it; or record and replay any sound within 15 ft.","Intaglio (GH14C)":"5 ft, up to 1 hour, Concentration. You turn parchment into a copy of a text or symbol. While concentrating, use an action to trace your hand over nonmagical text or imagery on a surface in range. You imprint it on parchment you provide, resizing or cropping as you choose. Each action copies one page and no more than a 9 by 12 inch section. When copying a spellbook this way, you follow the usual replacement rules but time and gp are halved.","Life Tether (GH14C)":"120 ft, up to 1 minute, Concentration. The target makes a Wisdom save. On a failure, a sickly green tether links you and it. When you take damage, each tethered target takes half that as Necrotic damage, after resistances and immunities. A target at 0 hit points is freed. As a bonus action you can move a tether from a fallen foe to another target, which makes a Wisdom save or is tethered. A target can have only one tether from any casting.\n\n**At Higher Levels.** At 4th level or higher you create one more tether for every two slot levels above 2nd.","Mirror Spell (GH14C)":"60 ft, instant. You take this reaction when you see a creature within 60 ft cast a spell. You try to copy and cast it. A spell of 2nd level or lower is copied automatically. For a spell of 3rd level or higher, make an ability check with your spellcasting ability against DC 10 plus the spell's level. On a success you copy it and cast it at its lowest level. You can copy only spells of a level no higher than the slot used for Mirror Spell. You can choose new targets. You cannot copy your own spell and can copy only spells cast by creatures. You count as the original caster, using your spellcasting modifier, save DC and attack bonus.\n\n**At Higher Levels.** At 4th level or higher you can copy a spell of equal or lower level.","Undead Enthrallment (GH14C)":"10 ft, instant, casting time 1 hour. Cast only at night. Choose corpses in range matching the size of what you raise, as the GM decides. A foul mimicry of life raises each as an undead of CR 3 or lower, with statistics from the GM. On each of your turns use a bonus action to command any of them within 60 ft, all alike or each separately, giving a specific order or a general one such as guarding a corridor. With no order, it only defends itself. It keeps following an order until done. It is under your control for 24 hours. To keep it longer, cast this spell on it again before the 24 hours end. That recast reasserts control over one creature instead of raising a new one, and the creature then stays permanently under your control. You can control at most four creatures with this spell."};
var IT=[["Aether Blood","Potion","Rare",0,"A glowing purple liquid. For 1 hour after you drink it, a spell slot you use counts as 1 level higher when setting the level the spell is cast at. A spell with no extra effect at higher levels gains nothing. Drink it a number of times equal to your Constitution modifier (minimum 1) and you become addicted. You must drink it again every 24 hours or have Disadvantage on Constitution checks and saves. The addiction ends with greater restoration or after 30 days without it.",{}],["Arc Rifle","Wondrous Item","Very Rare",0,"A rifle with glass tubes of sparking lightning, built by gnome engineers and illegal in most lands. It has 4 charges and regains 1d4 at dawn. Lightning Torrent: spend 1 charge as an action to fire a 60 ft line, 5 ft wide. Each creature in it makes a Dexterity save against your scatter save DC, taking 6d6 Lightning damage on a failure and half on a success. When you spend the last charge, roll a d20. On a 1 the rifle burns out and is useless.",{"ch":[4,"1d4","dawn"]}],["Breath of Beleth","Wondrous Item","Rare",0,"An airborne poison that conjures the victim's worst fears, breathed in to take effect. Inhaled: a creature makes a DC 15 Constitution save or is Poisoned for 1 minute. While Poisoned it is Frightened of every hostile creature it sees and must Dash away from them by the safest route each turn, unless it has nowhere to go.",{}],["Collar of Undead","Wondrous Item","Very Rare",0,"Put it on a Large or smaller humanoid that died within the last 10 days and it returns to life with 1 hit point as undead. It needs no food, sleep or air. At dawn each day its hit point maximum drops by 1d4, and at 0 hit points it falls to dust. While it wears the collar it obeys you. As a bonus action you can give it an order. With none it repeats the last order and defends itself. If the collar is taken off, the creature drops to 0 hit points at once.",{}],["Dreams Leaves","Potion","Uncommon",0,"A drug from a magically grown plant. Whoever consumes it falls into a trance for 1 hour and counts as unconscious. On waking, with its dreams and glimpses of its possible future, it gains 1 dream point. Being attacked or shaken ends the trance early with no point. It can spend the point as a reaction to gain Advantage on one attack roll, ability check or saving throw. Using it addicts you. You must consume it every 24 hours or have Disadvantage on Intelligence, Wisdom and Charisma checks and saves. The addiction ends with greater restoration or after 30 days without it.",{}],["Full Moon Extract","Potion","Uncommon",0,"A powder that brings a surge of strength. For 1 hour after you take it, your Strength is 19 (if lower) and you have Advantage on Strength checks and saves. Take it a number of times equal to your Constitution modifier plus 1 (minimum 1) and you become addicted. You must take it every 24 hours or have Disadvantage on Dexterity checks and saves. The addiction ends with greater restoration or after 30 days without it. If you take it while addicted, make a DC 6 Charisma save or you attack the nearest living creature you see until the effect ends.",{}],["Greatsword of the Craven","Weapon","Rare",1,"A greatsword with a +1 bonus to attack and damage. While attuned you gain 5 ft of speed and Advantage on initiative. It is cursed, and attuning extends the curse to you. You will not part with it and keep it on you. You have Disadvantage on attack rolls with any other weapon. When you try to pick up another weapon it shifts away, so you make a DC 10 Dexterity check or spend an action to grab it.",{"by":"a cowardly spirit","fx":{"atk":1,"dmg":1},"base":["Greatsword"]}],["Thought Talker Orbs","Wondrous Item","Uncommon",1,"Two small orbs, an emitter under half an inch across and a receiver. A creature holding both touches them together as an action to activate them. Then any creature that enters or starts its turn within 5 ft of the emitter makes a DC 13 Wisdom save. On a failure, an attuned creature holding the receiver learns its surface thoughts.",{}],["Shadow Steel Blades","Weapon","Very Rare",1,"Any melee weapon except a club, flail, greatclub, light hammer, mace, maul, morningstar, warhammer, whip or quarterstaff, made of Shadow Steel. It is forged from souls and hits with spiritual pain. You have Advantage on attack rolls against a target in medium or heavy armor. A creature you hit makes a DC 14 Constitution save or is Stunned until the end of its next turn.",{"base":["Longsword"]}]];
